        ("GET", "git.acme.com", "/org/repo"),
        ("GET", "x.y.acme.com", "/"),
        ("GET", "acme.com", "/"),
    ] {
        assert_eq!(
            forward.classify(method, host, path).await,
            reverse.classify(method, host, path).await,
