//! Host matching, precedence, and concurrent use through the public API.

use std::sync::Arc;

use action_classifier::{Classifier, load};

const ACME: &str = r#"
format_version = 1
name = "Acme"
description = "Acme API"
host = "acme.com"

[[rules]]
subdomain = "*"
action_class = "repo.read"

[[rules]]
subdomain = "api"
path = "/v1/*"
action_class = "payment.read"

[[rules]]
subdomain = "api"
method = "POST"
path = "/v1/*"
action_class = "payment.create"

[[rules]]
subdomain = "api"
path = "/v1/refunds/*"
action_class = "payment.refund"

[[rules]]
subdomain = "api"
path = "/v1/*/send"
action_class = "communication.external.send"

[[rules]]
path = "/pricing"
action_class = "payment.read"
"#;

#[tokio::test]
async fn host_patterns_respect_label_boundaries() {
    let c = load(&[ACME]).await.unwrap();
    let cases = [
        ("API.Acme.COM", Some("payment.read")),
        ("api.acme.com.", Some("payment.read")),
        ("api.acme.com:8443", Some("payment.read")),
        ("a.b.acme.com", Some("repo.read")),
        ("evilacme.com", None),
        ("api.acme.com.evil.com", None),
        ("acme.com.evil.com", None),
        ("user@api.acme.com", None),
        ("192.0.2.1", None),
    ];
    for (host, expected) in cases {
        assert_eq!(c.classify("GET", host, "/v1/x").await, expected, "{host}");
    }
    // `*` does not cover the bare host, and the bare-host rule only covers it.
    assert_eq!(c.classify("GET", "acme.com", "/v1/x").await, None);
    assert_eq!(
        c.classify("GET", "acme.com", "/pricing").await,
        Some("payment.read")
    );
    assert_eq!(
        c.classify("GET", "www.acme.com", "/pricing").await,
        Some("repo.read")
    );
}

#[tokio::test]
async fn most_specific_rule_wins() {
    let c = load(&[ACME]).await.unwrap();
    let cases = [
        // Exact subdomain beats wildcard subdomain even with a broader path.
        ("GET", "/v1/x", Some("payment.read")),
        // Explicit method beats omitted method once host and path tie.
        ("POST", "/v1/x", Some("payment.create")),
        // More literal characters beat a method on a broader pattern.
        ("POST", "/v1/refunds/r1", Some("payment.refund")),
        ("GET", "/v1/msg/send", Some("communication.external.send")),
        // A path no exact-host rule covers falls back to the wildcard host.
        ("GET", "/v2/x", Some("repo.read")),
    ];
    for (method, path, expected) in cases {
        assert_eq!(
            c.classify(method, "api.acme.com", path).await,
            expected,
            "{method} {path}"
        );
    }
}

#[tokio::test]
async fn malformed_requests_never_panic_or_classify() {
    let c = load(&[ACME]).await.unwrap();
    let long = "a".repeat(64 * 1024);
    let inputs: [(&str, &str, &str); 8] = [
        ("", "api.acme.com", "/v1/x"),
        ("GE T", "api.acme.com", "/v1/x"),
        ("GET", "", "/v1/x"),
        ("GET", "api.acme.com:", "/v1/x"),
        ("GET", "api.acme.com:99999", "/v1/x"),
        ("GET", "аpi.acme.com", "/v1/x"),
        ("GET", "api.acme.com", "/v1/\u{1F600}"),
        ("GET", "api.acme.com", "v1/x"),
    ];
    for (method, host, path) in inputs {
        assert_eq!(
            c.classify(method, host, path).await,
            None,
            "{method:?} {host:?} {path:?}"
        );
    }
    for value in [long.as_str(), "%", "%%%", "\0", "\u{10FFFF}"] {
        let _ = c.classify(value, value, value).await;
        let _ = c.classify("GET", "api.acme.com", value).await;
    }
}

#[test]
fn classifier_is_send_and_sync() {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<Classifier>();
}

#[test]
fn concurrent_classification_is_consistent() {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .build()
        .unwrap();
    let classifier = Arc::new(runtime.block_on(load(&[ACME])).unwrap());
    std::thread::scope(|scope| {
        for _ in 0..8 {
            let classifier = Arc::clone(&classifier);
            scope.spawn(move || {
                let runtime = tokio::runtime::Builder::new_current_thread()
                    .build()
                    .unwrap();
                for _ in 0..1_000 {
                    let (create, refund) = runtime.block_on(async {
                        (
                            classifier.classify("POST", "api.acme.com", "/v1/x").await,
                            classifier
                                .classify("POST", "api.acme.com", "/v1/refunds/r")
                                .await,
                        )
                    });
                    assert_eq!(create, Some("payment.create"));
                    assert_eq!(refund, Some("payment.refund"));
                }
            });
        }
    });
}

### tests/conflicts.rs
//! Load-time conflict detection and set-order independence.

use action_classifier::{LoadError, RuleLocation, SetError, load};

fn set(name: &str, host: &str, rules: &str) -> String {
    format!("format_version = 1\nname = {name:?}\ndescription = \"test\"\nhost = {host:?}\n{rules}")
}

fn rule(subdomain: Option<&str>, method: Option<&str>, path: Option<&str>, class: &str) -> String {
    let mut out = String::from("\n[[rules]]\n");
    for (key, value) in [("subdomain", subdomain), ("method", method), ("path", path)] {
        if let Some(value) = value {
            out.push_str(&format!("{key} = {value:?}\n"));
        }
    }
    out.push_str(&format!("action_class = {class:?}\n"));
    out
}

fn location(set: usize, name: &str, rule: usize) -> RuleLocation {
    RuleLocation {
        set,
        name: name.into(),
        rule,
    }
}

#[tokio::test]
async fn identical_rules_with_different_classes_conflict_across_sets() {
    let a = set(
        "A",
        "acme.com",
        &rule(
            Some("api"),
            Some("POST"),
            Some("/v1/refunds/*"),
            "payment.refund",
        ),
    );
    let b = set(
        "B",
        "acme.com",
        &format!(
            "{}{}",
            rule(None, None, Some("/pricing"), "payment.read"),
            rule(
                Some("api"),
                Some("POST"),
                Some("/v1/refunds/*"),
                "payment.read"
            ),
        ),
    );
    match load(&[&a, &b]).await {
        Err(LoadError::ConflictingRules { first, second }) => {
            assert_eq!(first, location(0, "A", 0));
            assert_eq!(second, location(1, "B", 1));
        }
        other => panic!("expected conflict, got {:?}", other.err()),
    }
}

#[tokio::test]
async fn conflict_message_names_both_rules() {
    let a = set("A", "acme.com", &rule(None, None, Some("/x"), "repo.read"));
    let b = set("B", "acme.com", &rule(None, None, Some("/x"), "repo.write"));
    let message = load(&[&a, &b]).await.err().unwrap().to_string();
    assert!(message.contains(r#"mapping set 0 "A" rule 0"#), "{message}");
    assert!(message.contains(r#"mapping set 1 "B" rule 0"#), "{message}");
}

#[tokio::test]
async fn conflicts_are_detected_within_one_set() {
    let a = set(
        "A",
        "acme.com",
        &format!(
            "{}{}",
            rule(None, None, Some("/x"), "repo.read"),
            rule(None, None, Some("/x"), "repo.write"),
        ),
    );
    assert!(matches!(
        load(&[&a]).await,
        Err(LoadError::ConflictingRules { .. })
    ));
}

#[tokio::test]
async fn overlapping_wildcards_with_equal_specificity_conflict() {
    // `/v1/xy` matches both patterns, and both have the same literal count,
    // wildcard count and literal prefix.
    let a = set(
        "A",
        "acme.com",
        &rule(None, None, Some("/v1/*x*"), "repo.read"),
    );
    let b = set(
        "B",
        "acme.com",
        &rule(None, None, Some("/v1/*y*"), "repo.write"),
    );
    assert!(matches!(
        load(&[&a, &b]).await,
        Err(LoadError::ConflictingRules { .. })
    ));
}

#[tokio::test]
async fn same_class_duplicates_are_harmless() {
    let a = set("A", "acme.com", &rule(None, None, Some("/x"), "repo.read"));
    let c = load(&[&a, &a]).await.unwrap();
    assert_eq!(c.classify("GET", "acme.com", "/x").await, Some("repo.read"));
}

#[tokio::test]
async fn overlaps_with_different_specificity_are_allowed() {
    let a = set("A", "acme.com", &rule(Some("*"), None, None, "repo.read"));
    let b = set(
        "B",
        "acme.com",
        &rule(Some("api"), Some("PUT"), Some("/repos/*"), "repo.write"),
    );
    let c = load(&[&a, &b]).await.unwrap();
    assert_eq!(
        c.classify("PUT", "api.acme.com", "/repos/x").await,
        Some("repo.write")
    );
    assert_eq!(
        c.classify("PUT", "www.acme.com", "/repos/x").await,
        Some("repo.read")
    );
}

#[tokio::test]
async fn rules_for_different_hosts_never_conflict() {
    let a = set("A", "acme.com", &rule(None, None, Some("/x"), "repo.read"));
    let b = set(
        "B",
        "other.com",
        &rule(None, None, Some("/x"), "repo.write"),
    );
    let c = rule(Some("api"), None, Some("/x"), "repo.write");
    let c = set("C", "acme.com", &c);
    assert!(load(&[&a, &b, &c]).await.is_ok());
}

#[tokio::test]
async fn exact_subdomain_and_bare_rule_on_the_same_host_conflict() {
    // Exact subdomains are one DNS label. These rules still name the same
    // origin and must be checked against each other.
    let a = set(
        "A",
        "eu.acme.com",
        &rule(Some("api"), None, None, "repo.read"),
    );
    let b = set(
        "B",
        "api.eu.acme.com",
        &rule(None, None, None, "repo.write"),
    );
    assert!(matches!(
        load(&[&a, &b]).await,
        Err(LoadError::ConflictingRules { .. })
    ));
}

#[tokio::test]
async fn set_order_does_not_change_classification() {
    let payments = set(
        "Payments",
        "acme.com",
        &format!(
            "{}{}{}",
            rule(Some("api"), None, Some("/v1/*"), "payment.read"),
            rule(Some("api"), None, Some("/v1/refunds/*"), "payment.refund"),
            rule(
                Some("api"),
                Some("POST"),
                Some("/v1/charges"),
                "payment.create"
            ),
        ),
    );
    let repos = set(
        "Repos",
        "acme.com",
        &format!(
            "{}{}",
            rule(Some("*"), None, None, "repo.read"),
            rule(Some("git"), Some("POST"), Some("/*"), "repo.write"),
        ),
    );
    let forward = load(&[&payments, &repos]).await.unwrap();
    let reverse = load(&[&repos, &payments]).await.unwrap();
    for (method, host, path) in [
        ("GET", "api.acme.com", "/v1/charges"),
        ("POST", "api.acme.com", "/v1/charges"),
        ("POST", "api.acme.com", "/v1/refunds/r1"),
        ("POST", "git.acme.com", "/org/repo"),
        ("GET", "git.acme.com", "/org/repo"),
        ("GET", "x.y.acme.com", "/"),
        ("GET", "acme.com", "/"),
    ] {
        assert_eq!(
            forward.classify(method, host, path).await,
            reverse.classify(method, host, path).await,
            "{method} {host}{path}"
        );
    }
}

#[tokio::test]
async fn invalid_set_errors_identify_set_name_and_rule() {
    let good = set("Good", "acme.com", &rule(None, None, None, "repo.read"));
    let bad = set(
        "Bad",
        "acme.com",
        &format!(
            "{}{}",
            rule(None, None, None, "repo.read"),
            rule(None, None, None, "payment.delete"),
        ),
    );
    match load(&[&good, &bad]).await {
        Err(LoadError::InvalidSet {
            set: 1,
            name: Some(name),
            error: SetError::UnknownActionClass { rule: 1, .. },
        }) => assert_eq!(name, "Bad"),
        other => panic!("unexpected {:?}", other.err()),
    }

    let unparsable = "format_version = 1\nnme = \"typo\"";
    match load(&[&good, unparsable]).await {
        Err(
            error @ LoadError::InvalidSet {
                set: 1, name: None, ..
            },
        ) => assert!(error.to_string().starts_with("mapping set 1: invalid TOML")),
        other => panic!("unexpected {:?}", other.err()),
    }
}

