#[test]
fn concurrent_classification_is_consistent() {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .build()
        .unwrap();
    let classifier = Arc::new(runtime.block_on(load(&[ACME])).unwrap());
    std::thread::scope(|scope| {
