  118	pub(crate) fn find_conflict(rules: &[CompiledRule]) -> Option<(usize, usize)> {
  119	    for (right_index, right) in rules.iter().enumerate() {
  120	        for (left_index, left) in rules[..right_index].iter().enumerate() {
  121	            if left.action_class != right.action_class
  122	                && left.specificity == right.specificity
  123	                && methods_overlap(left.method.as_deref(), right.method.as_deref())
  124	                && hosts_overlap(&left.host, &right.host)
  125	                && paths_overlap(left.path.as_deref(), right.path.as_deref())
  126	            {
